import React, { useState, useEffect } from 'react';
import { dbService } from '../services/storage';

function Management({ syncTrigger }) {
  const [catalog, setCatalog] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [newItem, setNewItem] = useState({
    id: null,
    name: '',
    shots: '',
    duration_s: '',
    description: '',
    wholesaler_link: '',
    size: 'N/A',
    shape: '',
    type: 'Cake',
    case_packing: '1'
  });

  // Search & Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState('All');
  const [filterSize, setFilterSize] = useState('All');
  const [filterShape, setFilterShape] = useState('All');

  const loadCatalog = () => {
    setCatalog(dbService.getCatalog());
  };

  useEffect(() => {
    loadCatalog();
  }, [syncTrigger]);

  const triggerBackgroundSync = async () => {
    const config = dbService.getSyncConfig();
    if (config.token) {
      try {
        const editor = localStorage.getItem('gbf_editor_name') || 'Planner';
        await dbService.syncToGitHub(editor);
        console.log('Background catalog auto-publish complete.');
      } catch (err) {
        console.warn('Background catalog auto-publish failed:', err);
      }
    }
  };

  const handlePullCatalog = async () => {
    if (!window.confirm("Do you want to sync the catalog with GitHub? This will pull any remote updates and merge them into your local database.")) return;
    try {
      await dbService.fetchFromGitHub();
      loadCatalog();
      alert("Catalog successfully synchronized with GitHub remote repository!");
    } catch (err) {
      alert(`Sync Failed: ${err.message}`);
    }
  };

  const handleManualAdd = (e) => {
    e.preventDefault();
    if (!newItem.name) return;

    dbService.saveCatalogItem({
      id: newItem.id || Date.now(),
      name: newItem.name,
      shots: parseInt(newItem.shots) || 0,
      duration_s: parseFloat(newItem.duration_s) || 0,
      description: newItem.description || '',
      wholesaler_link: newItem.wholesaler_link || '',
      size: newItem.size || 'N/A',
      shape: newItem.shape || '',
      type: newItem.type || 'Cake',
      case_packing: parseInt(newItem.case_packing) || 1
    });

    setShowModal(false);
    setNewItem({
      id: null,
      name: '',
      shots: '',
      duration_s: '',
      description: '',
      wholesaler_link: '',
      size: 'N/A',
      shape: '',
      type: 'Cake',
      case_packing: '1'
    });
    loadCatalog();
    triggerBackgroundSync();
  };

  const handleEdit = (item) => {
    setNewItem({
      id: item.id,
      name: item.name || '',
      shots: item.shots || '',
      duration_s: item.duration_s || '',
      description: item.description || '',
      wholesaler_link: item.wholesaler_link || '',
      size: item.size || 'N/A',
      shape: item.shape || '',
      type: item.type || 'Cake',
      case_packing: item.case_packing || '1'
    });
    setShowModal(true);
  };

  const handleDelete = (id, name) => {
    const confirmDel = window.confirm(`Are you sure you want to delete "${name}" from the catalog?`);
    if (!confirmDel) return;

    dbService.deleteCatalogItem(id);
    loadCatalog();
    triggerBackgroundSync();
  };

  const handleImportJson = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const items = JSON.parse(event.target.result);
        if (Array.isArray(items)) {
          dbService.importCatalog(items);
          loadCatalog();
          triggerBackgroundSync();
          alert(`Successfully imported ${items.length} fireworks from scraper catalog file!`);
        } else {
          alert('Invalid catalog format. File must contain an array of fireworks.');
        }
      } catch (err) {
        alert(`Failed to parse JSON file: ${err.message}`);
      }
    };
    reader.readAsText(file);
  };

  const handleResetCatalog = () => {
    if (window.confirm("Are you sure you want to reset the catalog? This will discard all scraped imports and manually added items, restoring the default catalog.")) {
      dbService.resetCatalog();
      loadCatalog();
      triggerBackgroundSync();
      alert("Catalog has been reset to defaults.");
    }
  };

  // Local filtering based on Search & Select Boxes
  const filteredCatalog = catalog.filter(item => {
    const matchesSearch =
      (item.name || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (item.description || '').toLowerCase().includes(searchTerm.toLowerCase());

    const matchesType = filterType === 'All' || item.type === filterType;
    const matchesSize = filterSize === 'All' || item.size === filterSize;
    const matchesShape = filterShape === 'All' || item.shape === filterShape;

    return matchesSearch && matchesType && matchesSize && matchesShape;
  });

  return (
    <div className="checkout-container fade-in">
      <div className="discovery-header-card" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div className="header-info">
          <h2>Wholesale Firework Catalog</h2>
          <p>Browse inventory specifications, update product details, or import raw scraper data files.</p>
        </div>
        <div style={{ display: 'flex', gap: '10px' }}>
          <button className="btn btn-secondary" onClick={handlePullCatalog} style={{ display: 'inline-flex', alignItems: 'center', borderColor: '#9b59b6', color: '#af7ac5' }}>
            ☁️ Sync with GitHub
          </button>
          <button className="btn btn-secondary" onClick={handleResetCatalog} style={{ display: 'inline-flex', alignItems: 'center' }}>
            🔄 Reset to Default
          </button>
          <label className="btn btn-secondary" style={{ cursor: 'pointer', margin: 0, display: 'inline-flex', alignItems: 'center' }}>
            📥 Import Scraped Catalog (.json)
            <input
              type="file"
              accept=".json"
              style={{ display: 'none' }}
              onChange={handleImportJson}
            />
          </label>
          <button 
            className="btn btn-primary" 
            onClick={() => {
              setNewItem({ id: null, name: '', shots: '', duration_s: '', description: '', wholesaler_link: '', size: 'N/A', shape: '', type: 'Cake' });
              setShowModal(true);
            }}
          >
            ➕ Add Catalog Item
          </button>
        </div>
      </div>

      {/* Search & Filters Registry Panel */}
      <div className="panel" style={{ marginTop: '20px', padding: '16px', display: 'flex', flexWrap: 'wrap', gap: '14px', alignItems: 'center' }}>
        <div style={{ flex: '1', minWidth: '240px' }}>
          <label className="input-label" style={{ marginBottom: '6px' }}>Search Firework Catalog</label>
          <input
            type="text"
            className="text-input"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Type name or description to filter..."
            style={{ width: '100%' }}
          />
        </div>
        <div style={{ width: '130px' }}>
          <label className="input-label" style={{ marginBottom: '6px' }}>Type</label>
          <select 
            className="text-input"
            value={filterType}
            onChange={(e) => setFilterType(e.target.value)}
            style={{ width: '100%', background: '#131324', color: '#fff', border: '1px solid rgba(255,255,255,0.08)' }}
          >
            <option value="All">All Types</option>
            <option value="Cake">Cake</option>
            <option value="Shell">Shell</option>
            <option value="Roman Candle">Roman Candle</option>
            <option value="Fountain">Fountain</option>
          </select>
        </div>
        <div style={{ width: '110px' }}>
          <label className="input-label" style={{ marginBottom: '6px' }}>Size</label>
          <select 
            className="text-input"
            value={filterSize}
            onChange={(e) => setFilterSize(e.target.value)}
            style={{ width: '100%', background: '#131324', color: '#fff', border: '1px solid rgba(255,255,255,0.08)' }}
          >
            <option value="All">All Sizes</option>
            <option value="500g">500g</option>
            <option value="200g">200g</option>
            <option value="N/A">N/A</option>
          </select>
        </div>
        <div style={{ width: '110px' }}>
          <label className="input-label" style={{ marginBottom: '6px' }}>Shape</label>
          <select 
            className="text-input"
            value={filterShape}
            onChange={(e) => setFilterShape(e.target.value)}
            style={{ width: '100%', background: '#131324', color: '#fff', border: '1px solid rgba(255,255,255,0.08)' }}
          >
            <option value="All">All Shapes</option>
            <option value="Straight">Straight</option>
            <option value="Fan">Fan</option>
            <option value="">N/A (Other)</option>
          </select>
        </div>
      </div>

      <div className="panel" style={{ marginTop: '20px' }}>
        {filteredCatalog.length === 0 ? (
          <div className="empty-state" style={{ padding: '60px' }}>
            <p>No matching catalog items found. Modify your filters or import products.</p>
          </div>
        ) : (
          <div className="nodes-table-wrapper" style={{ overflowY: 'auto', maxHeight: '68vh' }}>
            <table className="nodes-table">
              <thead>
                <tr>
                  <th style={{ width: '60px', textAlign: 'center' }}>ID</th>
                  <th>Firework Product Name</th>
                  <th style={{ width: '110px', textAlign: 'center' }}>Type</th>
                  <th style={{ width: '80px', textAlign: 'center' }}>Size</th>
                  <th style={{ width: '80px', textAlign: 'center' }}>Shape</th>
                  <th style={{ width: '80px', textAlign: 'center' }}>Shots</th>
                  <th style={{ width: '90px', textAlign: 'center' }}>Duration</th>
                  <th style={{ width: '80px', textAlign: 'center' }}>Packing</th>
                  <th>Description</th>
                  <th style={{ width: '120px', textAlign: 'center' }}>Link</th>
                  <th style={{ width: '140px', textAlign: 'center' }}>Action</th>
                </tr>
              </thead>
              <tbody>
                {filteredCatalog.map((item) => (
                  <tr key={item.id}>
                    <td style={{ textAlign: 'center', fontWeight: 'bold', color: 'var(--text-muted)' }}>#{item.id}</td>
                    <td>
                      <strong style={{ fontSize: '13.5px', color: '#fff' }}>{item.name}</strong>
                    </td>
                    <td style={{ textAlign: 'center' }}>
                      <span className="node-badge" style={{ backgroundColor: 'rgba(56, 189, 248, 0.12)', color: '#38bdf8', border: '1px solid rgba(56,189,248,0.2)' }}>
                        {item.type || 'Cake'}
                      </span>
                    </td>
                    <td style={{ textAlign: 'center' }}>
                      <span className="node-badge" style={{ 
                        backgroundColor: item.size === '500g' ? 'rgba(236, 72, 153, 0.12)' : item.size === '200g' ? 'rgba(251, 191, 36, 0.12)' : 'rgba(255,255,255,0.05)', 
                        color: item.size === '500g' ? '#f472b6' : item.size === '200g' ? '#fbbf24' : 'var(--text-secondary)', 
                        border: item.size === '500g' ? '1px solid rgba(236,72,153,0.2)' : item.size === '200g' ? '1px solid rgba(251,191,36,0.2)' : '1px solid rgba(255,255,255,0.1)' 
                      }}>
                        {item.size || 'N/A'}
                      </span>
                    </td>
                    <td style={{ textAlign: 'center' }}>
                      {item.shape ? (
                        <span className="node-badge" style={{ backgroundColor: 'rgba(16, 185, 129, 0.12)', color: '#34d399', border: '1px solid rgba(16,185,129,0.2)' }}>
                          {item.shape}
                        </span>
                      ) : (
                        <span style={{ color: 'var(--text-muted)', fontSize: '12px' }}>-</span>
                      )}
                    </td>
                    <td style={{ textAlign: 'center', fontWeight: 'bold' }}>{item.shots || 'N/A'}</td>
                    <td style={{ textAlign: 'center', fontWeight: 'bold' }}>{item.duration_s ? `${item.duration_s}s` : 'N/A'}</td>
                    <td style={{ textAlign: 'center', fontWeight: '500' }}>{item.case_packing ? `${item.case_packing}:1` : '1:1'}</td>
                    <td style={{ fontSize: '12.5px', color: 'var(--text-secondary)' }}>{item.description || 'No description available'}</td>
                    <td style={{ textAlign: 'center' }}>
                      {item.wholesaler_link ? (
                        <a 
                          href={item.wholesaler_link} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="node-badge"
                          style={{ backgroundColor: 'rgba(99, 102, 241, 0.12)', color: '#a5b4fc', border: '1px solid rgba(99,102,241,0.25)', textDecoration: 'none' }}
                        >
                          🔗 Red Rhino
                        </a>
                      ) : (
                        <span style={{ fontSize: '11px', color: 'var(--text-muted)' }}>N/A</span>
                      )}
                    </td>
                    <td style={{ textAlign: 'center' }}>
                      <div style={{ display: 'flex', gap: '6px', justifyContent: 'center' }}>
                        <button 
                          className="btn btn-secondary btn-sm" 
                          style={{ borderColor: 'var(--primary)', color: 'var(--primary)', padding: '3px 8px', fontSize: '11.5px' }}
                          onClick={() => handleEdit(item)}
                        >
                          Edit
                        </button>
                        <button 
                          className="btn btn-secondary btn-sm" 
                          style={{ borderColor: '#ff4d4d', color: '#ff4d4d', padding: '3px 8px', fontSize: '11.5px' }}
                          onClick={() => handleDelete(item.id, item.name)}
                        >
                          Delete
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showModal && (
        <div className="modal-backdrop" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: '500px' }}>
            <div className="modal-header">
              <h3>{newItem.id ? '✏️ Edit Catalog Product' : '➕ Add Wholesale Catalog Product'}</h3>
              <button className="close-btn" onClick={() => setShowModal(false)}>&times;</button>
            </div>
            <form onSubmit={handleManualAdd}>
              <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
                <div>
                  <label className="input-label">Firework Name</label>
                  <input
                    type="text"
                    className="text-input"
                    value={newItem.name}
                    onChange={(e) => setNewItem({ ...newItem, name: e.target.value })}
                    placeholder="e.g. Loaded Gun"
                    required
                    style={{ width: '100%' }}
                  />
                </div>
                
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px' }}>
                  <div>
                    <label className="input-label">Type</label>
                    <select
                      className="text-input"
                      value={newItem.type}
                      onChange={(e) => setNewItem({ ...newItem, type: e.target.value })}
                      style={{ width: '100%', background: '#131324', color: '#fff', border: '1px solid rgba(255,255,255,0.08)' }}
                    >
                      <option value="Cake">Cake</option>
                      <option value="Shell">Shell</option>
                      <option value="Roman Candle">Roman Candle</option>
                      <option value="Fountain">Fountain</option>
                    </select>
                  </div>
                  <div>
                    <label className="input-label">Size</label>
                    <select
                      className="text-input"
                      value={newItem.size}
                      onChange={(e) => setNewItem({ ...newItem, size: e.target.value })}
                      style={{ width: '100%', background: '#131324', color: '#fff', border: '1px solid rgba(255,255,255,0.08)' }}
                    >
                      <option value="500g">500g</option>
                      <option value="200g">200g</option>
                      <option value="N/A">N/A</option>
                    </select>
                  </div>
                  <div>
                    <label className="input-label">Shape</label>
                    <select
                      className="text-input"
                      value={newItem.shape}
                      onChange={(e) => setNewItem({ ...newItem, shape: e.target.value })}
                      style={{ width: '100%', background: '#131324', color: '#fff', border: '1px solid rgba(255,255,255,0.08)' }}
                    >
                      <option value="">N/A (Other)</option>
                      <option value="Straight">Straight</option>
                      <option value="Fan">Fan</option>
                    </select>
                  </div>
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px' }}>
                  <div>
                    <label className="input-label">Total Shots</label>
                    <input
                      type="number"
                      className="text-input"
                      value={newItem.shots}
                      onChange={(e) => setNewItem({ ...newItem, shots: e.target.value })}
                      placeholder="e.g. 36"
                      style={{ width: '100%' }}
                    />
                  </div>
                  <div>
                    <label className="input-label">Duration (sec)</label>
                    <input
                      type="number"
                      step="0.1"
                      className="text-input"
                      value={newItem.duration_s}
                      onChange={(e) => setNewItem({ ...newItem, duration_s: e.target.value })}
                      placeholder="e.g. 25"
                      style={{ width: '100%' }}
                    />
                  </div>
                  <div>
                    <label className="input-label">Case Packing</label>
                    <input
                      type="number"
                      className="text-input"
                      value={newItem.case_packing}
                      onChange={(e) => setNewItem({ ...newItem, case_packing: e.target.value })}
                      placeholder="e.g. 4"
                      style={{ width: '100%' }}
                    />
                  </div>
                </div>
                <div>
                  <label className="input-label">Description / Effect Text</label>
                  <input
                    type="text"
                    className="text-input"
                    value={newItem.description}
                    onChange={(e) => setNewItem({ ...newItem, description: e.target.value })}
                    placeholder="e.g. Color-changing pearls to crackling flowers."
                    style={{ width: '100%' }}
                  />
                </div>
                <div>
                  <label className="input-label">Wholesaler Link URL</label>
                  <input
                    type="url"
                    className="text-input"
                    value={newItem.wholesaler_link}
                    onChange={(e) => setNewItem({ ...newItem, wholesaler_link: e.target.value })}
                    placeholder="e.g. https://www.redrhinofireworks.com/..."
                    style={{ width: '100%' }}
                  />
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary">{newItem.id ? 'Save Changes' : 'Add Product'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default Management;
